#include "AuxRouting.h"
static Project auxFixture(){auto p=emptyProject();p.songMode=true;p.loop=false;p.bpm=120;p.master=.5f;p.delayReturn=0;p.tracks[7].instrument=Instrument::analog;p.tracks[7].volume=.3f;p.tracks[7].cutoff=20000;p.patterns[0].length=4;p.patterns[0].lanes[7]={{0,4,48,.8f}};for(int i=0;i<2;++i){Track bus;bus.isBus=true;bus.volume=1;bus.cutoff=20000;bus.name=i?"Delay bus":"Reverb bus";p.tracks.push_back(bus);}p.patterns[0].lanes.resize(p.tracks.size());p.clips={{7,0,0,4}};return p;}
static void testAuxSends(const File& root,Assets& assets){
    auto source=auxFixture();auto original=JSON::toString(projectToJson(source));auto routed=source;routed.tracks[7].auxSends[0]={8,.5f,false};routed.tracks[7].auxSends[1]={9,.25f,false};std::array<int,maxTracks> order{};
    expect(validateRouting(routed,&order).wasOk()&&std::find(order.begin(),order.begin()+10,7)<std::find(order.begin(),order.begin()+10,8),"multiple independent auxiliary bus paths join the topological routing order");
    auto dry=render(source,assets,root,48000,127);auto parallel=render(routed,assets,root,48000,127);double error=0;for(int c=0;c<2;++c)for(int i=12000;i<48000;++i)error=jmax(error,std::abs(parallel.getSample(c,i)-dry.getSample(c,i)*1.75));expect(error<1e-6,"two post-fader parallel buses add their levels to the unchanged primary path after the bounded startup ramps");expect(parallel==render(routed,assets,root,48000,1024),"auxiliary processing is sample-exact across callback block sizes");
    auto zero=routed;zero.tracks[7].auxSends[0].level=zero.tracks[7].auxSends[1].level=0;expect(dry==render(zero,assets,root,48000,257),"zero-level sends are acoustically transparent");
    auto pre=source;pre.tracks[7].volume=0;pre.tracks[7].auxSends[0]={8,.5f,true};auto preAudio=render(pre,assets,root,48000,128);expect(preAudio.getMagnitude(0,12000,24000)>.001f,"pre-fader send remains audible with channel volume at zero");auto post=pre;post.tracks[7].auxSends[0].preFader=false;expect(render(post,assets,root,48000,128).getMagnitude(0,12000,24000)==0,"post-fader send follows zero channel volume");auto muted=pre;muted.tracks[7].mute=true;expect(render(muted,assets,root,48000,128).getMagnitude(0,0,48000)==0,"channel Mute closes pre-fader sends too");muted=pre;muted.tracks[8].mute=true;expect(render(muted,assets,root,48000,128).getMagnitude(0,0,48000)==0,"bus Mute closes the auxiliary return");
    auto solo=routed;solo.tracks[8].solo=true;auto graph=routingAudibility(solo);expect((graph.inputs&(1u<<7))&&!(graph.edges[7]&1)&&(graph.edges[7]&2)&&!(graph.edges[7]&4),"Solo on an auxiliary bus retains its feeder path and excludes dry and sibling-return paths");auto soloAudio=render(solo,assets,root,48000,127);error=0;for(int c=0;c<2;++c)for(int i=12000;i<48000;++i)error=jmax(error,std::abs(soloAudio.getSample(c,i)-dry.getSample(c,i)*.5));expect(error<1e-6,"soloed auxiliary return contains no dry or sibling bus leakage");solo=routed;solo.tracks[7].solo=true;expect(render(solo,assets,root,48000,127)==parallel,"source Solo retains all of its parallel returns");
    auto nested=routed;nested.tracks[8].auxSends[0]={9,.25f,false};expect(validateRouting(nested).wasOk()&&render(nested,assets,root,48000,127).getMagnitude(0,12000,24000)>parallel.getMagnitude(0,12000,24000),"buses can send onward to other buses in a bounded acyclic graph");auto cycle=nested;cycle.tracks[9].auxSends[0]={8,0,true};expect(validateRouting(cycle).failed(),"zero-level auxiliary feedback cycles reject before playback");cycle=routed;cycle.tracks[8].mixer.output=7;expect(validateRouting(cycle).failed(),"mixed primary/auxiliary routing cycles reject");for(int target:{-2,7,15,0}){auto bad=source;bad.tracks[7].auxSends[0].target=target;expect(validateRouting(bad).failed(),"invalid, self, missing and non-bus auxiliary destinations reject");}
    for(float level:{-1.f,1.501f,std::numeric_limits<float>::infinity(),std::numeric_limits<float>::quiet_NaN()}){auto bad=routed;bad.tracks[7].auxSends[0].level=level;expect(validateRouting(bad).failed(),"invalid auxiliary levels cannot reach the callback");}
    auto file=root.getChildFile("aux-sends.pulse");Project loaded;expect(saveProject(routed,file).wasOk()&&loadProject(file,loaded).wasOk()&&loaded.tracks[7].auxSends==routed.tracks[7].auxSends&&JSON::toString(projectToJson(loaded))==JSON::toString(projectToJson(routed)),"schema 34 persists all four destinations levels and tap modes");
    auto old=projectToJson(source);old.getDynamicObject()->setProperty("schema",33);for(auto& track:*old["tracks"].getArray())track.getDynamicObject()->removeProperty("auxSends");expect(projectFromJson(old,loaded).wasOk()&&loaded.tracks[7].auxSends==AuxSends{}&&render(loaded,assets,root,48000,127)==dry,"schema 33 migrates missing sends to Off with identical legacy audio");auto invalid=projectToJson(routed);invalid.getDynamicObject()->setProperty("schema",33);auto token=JSON::toString(projectToJson(loaded));expect(projectFromJson(invalid,loaded).failed()&&JSON::toString(projectToJson(loaded))==token,"active auxiliary routes mislabeled with an older schema reject atomically");invalid=projectToJson(source);invalid["tracks"][7].getDynamicObject()->removeProperty("auxSends");expect(projectFromJson(invalid,loaded).failed(),"schema 34 requires explicit send slots");
    AuxSends parsed;auto encoded=auxSendsToJson(routed.tracks[7].auxSends);expect(auxSendsFromJson(encoded,parsed).wasOk()&&parsed==routed.tracks[7].auxSends,"auxiliary JSON round trips exactly");for(auto text:{"[]","null",R"([{"target":8,"level":0.5,"preFader":true}])"})expect(auxSendsFromJson(JSON::parse(text),parsed).failed(),"missing and short send arrays reject");for(auto bad:{var(true),var("0.5"),var(-1),var(1.6)}){auto json=auxSendsToJson(parsed);json[0].getDynamicObject()->setProperty("level",bad);expect(auxSendsFromJson(json,parsed).failed(),"send levels use strict numeric bounds");}for(auto field:{"target","level","preFader"}){auto json=auxSendsToJson(parsed);json[0].getDynamicObject()->removeProperty(field);expect(auxSendsFromJson(json,parsed).failed(),"every send field is required");}
    expect(auxTopologyChanged(source,zero)&&auxTopologyChanged(source,routed),"new routes require transport refresh");auto levelOnly=routed;levelOnly.tracks[7].auxSends[0].level=.8f;expect(!auxTopologyChanged(routed,levelOnly),"level-only changes retain running effect history");
    auto operation=var(new DynamicObject());operation.getDynamicObject()->setProperty("op","set_track");operation.getDynamicObject()->setProperty("track",7);operation.getDynamicObject()->setProperty("auxSends",auxSendsToJson(routed.tracks[7].auxSends));Project edited;expect(applyControlEdits(source,var(Array<var>{operation}),edited).wasOk()&&edited.tracks[7].auxSends==routed.tracks[7].auxSends,"MCP track edits share auxiliary route validation");
    auto malformed=JSON::parse(JSON::toString(operation));malformed["auxSends"][0].getDynamicObject()->setProperty("target",7);auto before=JSON::toString(projectToJson(edited));expect(applyControlEdits(source,var(Array<var>{malformed}),edited).failed()&&JSON::toString(projectToJson(edited))==before,"self-send MCP edit rejects without replacing the candidate");
    RenderSettings settings;settings.normalize=false;settings.bits=24;auto stem=root.getChildFile("aux-return.wav");expect(renderAudio(routed,assets,root,stem,settings,8).wasOk(),"offline bus stem export accepts auxiliary-only feeders");String message;auto decoded=assets.load(stem,message);expect(decoded&&decoded->audio.getMagnitude(0,12000,24000)>.001f,"auxiliary-only bus stem contains its real feeder audio");
    auto engine=makeEngine(routed,assets,root);AudioBuffer<float> live(2,24000);engine->render(live.getWritePointer(0),live.getWritePointer(1),24000);String warnings;expect(compilePlayback(levelOnly,assets,root,engine->exchange.beginWrite(),warnings).wasOk(),"live send level update compiles");engine->exchange.publish();AudioBuffer<float> update(2,512);engine->render(update.getWritePointer(0),update.getWritePointer(1),512);expect(engine->playing.load()&&update.getMagnitude(0,0,512)>.001f,"level-only publication continues playing without losing held voices");
    auto empty=emptyProject();empty.songMode=false;auto timing=makeEngine(empty,assets,root);AudioBuffer<float> transition(2,512);timing->render(transition.getWritePointer(0),transition.getWritePointer(1),512);timing->resetRequested.store(true);timing->render(transition.getWritePointer(0),transition.getWritePointer(1),512);
    expect(timing->position.load()>0,"an in-flight old empty snapshot can consume an earlier reset before history publication");
    auto restored=source;warnings.clear();bool restoredOk=compilePlayback(restored,assets,root,timing->exchange.beginWrite(),warnings).wasOk();timing->exchange.publish(true);restored.tracks[7].volume=.4f;restoredOk&=compilePlayback(restored,assets,root,timing->exchange.beginWrite(),warnings).wasOk();timing->exchange.publish();timing->render(transition.getWritePointer(0),transition.getWritePointer(1),512);auto fresh=render(restored,assets,root,512,512);
    expect(restoredOk&&transition==fresh&&transition.getMagnitude(0,0,512)>.001f,"history reset travels with the new snapshot, survives coalescing and cannot miss its first held note");double advanced=timing->position.load();timing->render(transition.getWritePointer(0),transition.getWritePointer(1),512);expect(timing->position.load()>advanced,"snapshot reset is consumed once instead of restarting every callback");
    expect(JSON::toString(projectToJson(source))==original,"all auxiliary transforms leave the input project intact");
}
